#!/usr/bin/env python3
import struct
import sys

TARGET = 64
DEPTH = 65


def chunks(blob):
    assert blob[:4] == b"DXBC", "not a DXBC container"
    count = struct.unpack_from("<I", blob, 28)[0]
    offsets = struct.unpack_from(f"<{count}I", blob, 32)
    for offset in offsets:
        tag = blob[offset:offset + 4].decode()
        size = struct.unpack_from("<I", blob, offset + 4)[0]
        yield tag, blob[offset + 8:offset + 8 + size]


def signature(data, tag):
    count = struct.unpack_from("<I", data, 0)[0]
    stride = {"ISGN": 24, "OSGN": 24, "PCSG": 24, "OSG5": 28, "ISG1": 32, "OSG1": 32, "PSG1": 32}[tag]
    entries = []
    for index in range(count):
        at = 8 + index * stride
        stream = 0
        if tag in ("OSG5", "ISG1", "OSG1", "PSG1"):
            stream = struct.unpack_from("<I", data, at)[0]
            at += 4
        _name, _index, sv, component, register, mask, _rw = struct.unpack_from("<IIIIIBB", data, at)
        precision = struct.unpack_from("<I", data, at + 24)[0] if tag.endswith("1") else 0
        if sv in (TARGET, DEPTH):
            sv = 0
        entries.append((sv, register, mask, component, precision, stream))
    return entries


def main():
    name, path = sys.argv[1], sys.argv[2]
    blob = open(path, "rb").read()
    code, inputs, outputs = b"", [], []
    for tag, data in chunks(blob):
        if tag in ("SHDR", "SHEX"):
            code = data
        elif tag in ("ISGN", "ISG1"):
            inputs = signature(data, tag)
        elif tag in ("OSGN", "OSG1", "OSG5"):
            outputs = signature(data, tag)
    words = struct.unpack(f"<{len(code) // 4}I", code)
    print(f"/* {name}: generated by tests/fixtures/d3d/ddi_shader_fixture.py from {path.split('/')[-1]}. */")
    print("#pragma once\n\n#include \"proto/generated/d3d/d3d_wire_types.h\"\n\n#include <cstdint>\n")
    print(f"namespace {name} {{\n")
    print(f"inline constexpr std::uint32_t tokens[] = {{")
    for row in range(0, len(words), 8):
        print("    " + ", ".join(f"0x{w:08x}u" for w in words[row:row + 8]) + ",")
    print("};\n")
    for label, entries in (("inputs", inputs), ("outputs", outputs)):
        print(f"inline constexpr av::d3dproto::SignatureEntry {label}[] = {{")
        for entry in entries:
            print("    {" + ", ".join(f"{v}u" for v in entry) + "},")
        if not entries:
            print("    {0u, 0u, 0u, 0u, 0u, 0u},")
        print("};")
        print(f"inline constexpr std::uint32_t {label}_count = {len(entries)}u;\n")
    print(f"}}  // namespace {name}")


if __name__ == "__main__":
    main()
